import {
  createContext,
  useContext,
  useId,
  useLayoutEffect,
  useRef,
  type KeyboardEvent,
  type ReactNode,
} from 'react';
import { rovingIndex } from '../../../primitives/roving';
import { useControllableState } from '../../../primitives/use-controllable-state';
import './tab-bar.css';

type Activation = 'automatic' | 'manual';

interface TabsContextValue {
  baseId: string;
  value: string;
  select: (value: string) => void;
  activation: Activation;
}

const TabsContext = createContext<TabsContextValue | null>(null);

function useTabs(part: string): TabsContextValue {
  const context = useContext(TabsContext);
  if (!context) throw new Error(`<${part}> must be used inside <Tabs>.`);
  return context;
}

const safe = (value: string) => value.replace(/[^\w-]/g, '_');
const tabId = (base: string, value: string) => `${base}-tab-${safe(value)}`;
const panelId = (base: string, value: string) => `${base}-panel-${safe(value)}`;

export interface TabsProps {
  /** Selected tab (controlled). */
  value?: string;
  /** Initially selected tab (uncontrolled). */
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /**
   * `automatic` selects a tab as soon as it receives focus. `manual` waits for Enter or
   * Space, which suits panels that are slow to render.
   */
  activation?: Activation;
  className?: string;
  children: ReactNode;
}

export function Tabs({
  value,
  defaultValue = '',
  onValueChange,
  activation = 'automatic',
  className,
  children,
}: TabsProps) {
  const baseId = useId();
  const [selected, setSelected] = useControllableState({
    value,
    defaultValue,
    onChange: onValueChange,
  });
  return (
    <TabsContext.Provider value={{ baseId, value: selected, select: setSelected, activation }}>
      <div className={['atl-tabs', className].filter(Boolean).join(' ')}>{children}</div>
    </TabsContext.Provider>
  );
}

export interface TabBarProps {
  /** Accessible name for the tab list, for example "Documentation sections". */
  label: string;
  /** `line` draws a magenta rule under the selected tab; `chip` slides a filled chip behind it. */
  variant?: 'line' | 'chip';
  className?: string;
  children: ReactNode;
}

export function TabBar({ label, variant = 'line', className, children }: TabBarProps) {
  const { value, select, activation } = useTabs('TabBar');
  const listRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const list = listRef.current;
    if (!list) return;
    const measure = () => {
      const tab = list.querySelector<HTMLElement>('[role="tab"][aria-selected="true"]');
      if (!tab) {
        list.style.setProperty('--atl-indicator-w', '0px');
        return;
      }
      list.style.setProperty('--atl-indicator-x', `${tab.offsetLeft}px`);
      list.style.setProperty('--atl-indicator-w', `${tab.offsetWidth}px`);
    };
    measure();
    // Only animate after the first placement, so the indicator does not slide in from 0.
    const frame = requestAnimationFrame(() => list.setAttribute('data-ready', ''));
    const observer = new ResizeObserver(measure);
    observer.observe(list);
    list.querySelectorAll('[role="tab"]').forEach((tab) => observer.observe(tab));
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, [value, children]);

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const tabs = Array.from(
      event.currentTarget.querySelectorAll<HTMLButtonElement>('[role="tab"]:not(:disabled)'),
    );
    const current = tabs.indexOf(document.activeElement as HTMLButtonElement);
    const rtl = getComputedStyle(event.currentTarget).direction === 'rtl';
    const next = rovingIndex(event.key, current, tabs.length, { orientation: 'horizontal', rtl });
    if (next === null || current === -1) return;
    event.preventDefault();
    const tab = tabs[next];
    if (!tab) return;
    tab.focus();
    tab.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    if (activation === 'automatic' && tab.dataset.value) select(tab.dataset.value);
  };

  return (
    // The tabs inside are focusable; the list only handles their arrow keys.
    // eslint-disable-next-line jsx-a11y/interactive-supports-focus
    <div
      ref={listRef}
      role="tablist"
      aria-label={label}
      aria-orientation="horizontal"
      className={['atl-tabbar', className].filter(Boolean).join(' ')}
      data-variant={variant}
      onKeyDown={onKeyDown}
    >
      <span className="atl-tabbar__indicator" aria-hidden="true" />
      {children}
    </div>
  );
}

export interface TabProps {
  value: string;
  disabled?: boolean;
  children: ReactNode;
}

export function Tab({ value, disabled = false, children }: TabProps) {
  const { baseId, value: selected, select } = useTabs('Tab');
  const isSelected = value === selected;
  return (
    <button
      type="button"
      role="tab"
      id={tabId(baseId, value)}
      aria-selected={isSelected}
      aria-controls={panelId(baseId, value)}
      tabIndex={isSelected ? 0 : -1}
      disabled={disabled}
      data-value={value}
      className="atl-tab"
      onClick={() => select(value)}
    >
      {children}
    </button>
  );
}

export interface TabPanelProps {
  value: string;
  className?: string;
  children: ReactNode;
}

export function TabPanel({ value, className, children }: TabPanelProps) {
  const { baseId, value: selected } = useTabs('TabPanel');
  const hidden = value !== selected;
  return (
    <div
      role="tabpanel"
      id={panelId(baseId, value)}
      aria-labelledby={tabId(baseId, value)}
      hidden={hidden}
      tabIndex={0}
      className={['atl-tabpanel', className].filter(Boolean).join(' ')}
    >
      {hidden ? null : children}
    </div>
  );
}

@layer atlas.components {
  .atl-tabbar {
    position: relative;
    display: flex;
    gap: var(--space-3xs);
    overflow-x: auto;
    overscroll-behavior-x: contain;
    scrollbar-width: none;
  }

  .atl-tabbar::-webkit-scrollbar {
    display: none;
  }

  .atl-tab {
    position: relative;
    z-index: 1;
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    flex: none;
    min-height: var(--target-comfort);
    padding: 0 var(--space-m);
    border: 0;
    background: none;
    color: var(--ink-soft);
    font-size: var(--step-0);
    font-weight: 500;
    white-space: nowrap;
    transition:
      color var(--dur-tick) var(--ease-anchor),
      background-color var(--dur-tick) var(--ease-anchor);
  }

  .atl-tab:hover:not(:disabled) {
    color: var(--ink);
  }

  .atl-tab[aria-selected='true'] {
    color: var(--ink);
  }

  .atl-tab:disabled {
    cursor: not-allowed;
    opacity: 0.55;
  }

  .atl-tab:focus-visible {
    outline-offset: -3px;
  }

  .atl-tabbar__indicator {
    position: absolute;
    left: 0;
    width: var(--atl-indicator-w, 0px);
    transform: translateX(var(--atl-indicator-x, 0px));
    pointer-events: none;
  }

  .atl-tabbar[data-ready] .atl-tabbar__indicator {
    transition:
      transform var(--dur-current) var(--ease-current),
      width var(--dur-current) var(--ease-current);
  }

  /* line: a magenta course line under the selected tab, over a faint isobath track */
  .atl-tabbar[data-variant='line'] {
    box-shadow: inset 0 -1px 0 color-mix(in oklch, var(--isobath) 65%, transparent);
  }

  .atl-tabbar[data-variant='line'] .atl-tab {
    border-radius: var(--radius-control) var(--radius-control) 0 0;
  }

  .atl-tabbar[data-variant='line'] .atl-tab:hover:not(:disabled) {
    background: var(--ink-wash);
  }

  .atl-tabbar[data-variant='line'] .atl-tabbar__indicator {
    bottom: 0;
    height: 3px;
    border-radius: 3px 3px 0 0;
    background: var(--chart-magenta);
  }

  /* chip: a raised chip that slides behind the selected tab */
  .atl-tabbar[data-variant='chip'] {
    width: fit-content;
    max-width: 100%;
    padding: var(--space-2xs);
    border-radius: var(--radius-panel);
    background: var(--shoal);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--isobath) 55%, transparent);
  }

  .atl-tabbar[data-variant='chip'] .atl-tab {
    min-height: calc(var(--target-comfort) - 4px);
    border-radius: calc(var(--radius-panel) - 4px);
  }

  .atl-tabbar[data-variant='chip'] .atl-tabbar__indicator {
    top: var(--space-2xs);
    bottom: var(--space-2xs);
    border-radius: calc(var(--radius-panel) - 4px);
    background: var(--reef);
    box-shadow:
      inset 0 0 0 1px var(--edge),
      inset 0 -2px 0 var(--chart-magenta);
  }

  .atl-tabpanel {
    transition:
      opacity var(--dur-step) var(--ease-anchor),
      translate var(--dur-step) var(--ease-anchor);
  }

  @starting-style {
    .atl-tabpanel:not([hidden]) {
      opacity: 0;
      translate: 0 6px;
    }
  }

  .atl-tabpanel:focus-visible {
    outline-offset: 6px;
    border-radius: var(--radius-control);
  }

  @media (forced-colors: active) {
    .atl-tabbar__indicator {
      background: Highlight !important;
    }
    .atl-tab[aria-selected='true'] {
      text-decoration: underline;
    }
  }
}
